program = '''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    gap_columns = set()
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if grid[r][c] == 0 and color != 0 and grid[r][c + 1] == color:
                out[r][c] = color
                gap_columns.add(c)
    for c in gap_columns:
        for r in range(h):
            color = out[r][c]
            if color == 0:
                continue
            rr = r - 1
            while rr >= 0 and out[rr][c] == 0:
                out[rr][c] = color
                rr -= 1
    return out
'''
